import {audioSettings,audioBeats} from './beat-audio-core.js';
import {patternBeats} from './beat-instruments.js';
import {playlistEnd,PLAYLIST_LIMITS} from './beat-playlist.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createPlaylistEditor(root,{getState,getPatterns,getBpm=()=>100,currentId,uid,changed,changing=()=>{},editPattern,savePattern,addPattern,restore,seek,exportSong,notify}){
 let selection=new Set(),clipboard=[],undo=[],redo=[],position=0,gestures=new Map(),source='',multi=false;
 const state=()=>getState(),snapshot=()=>structuredClone({playlist:state(),patterns:getPatterns()}),remember=()=>{undo.push(snapshot());if(undo.length>40)undo.shift();redo=[];},finish=()=>{changed();render();},act=fn=>{try{changing();remember();fn();finish();}catch(e){const old=undo.pop();if(old)restore(old);notify(e.message,'error');render();}},selected=()=>state().clips.filter(c=>selection.has(c.id)),q=s=>root.querySelector(s),all=s=>root.querySelectorAll(s),snap=n=>Math.round(n/state().snap)*state().snap;
 const duration=p=>p.kind==='audio'?audioBeats(p,getBpm()):patternBeats(p);
 function place(patternId,trackId,start){if(state().clips.length>=512)throw Error('Keep this song within 512 clips.');const pattern=getPatterns().find(p=>p.id===patternId);if(!pattern)throw Error('Choose a pattern.');if(!['notes','audio'].includes(pattern.kind)&&!pattern.playlistPads)savePattern(patternId);const c={id:uid(),patternId,trackId,start:Math.max(0,Math.min(512-Math.max(.125,duration(pattern)),start)),length:Math.max(.125,duration(pattern)),offset:0};state().clips.push(c);selection=new Set([c.id]);}
 function preview(p,c){if(p.kind==='audio'){const settings=audioSettings(p),cycle=audioBeats(p,getBpm()),bins=Math.min(1024,Math.max(32,Math.ceil(c.length*state().zoom)));return `<svg viewBox="0 0 ${bins} 100" aria-hidden="true" preserveAspectRatio="none">${Array.from({length:bins},(_,i)=>{const phase=((c.offset+i/bins*c.length)%cycle)/cycle,source=settings.start+phase*(settings.end-settings.start),[lo,hi]=p.wave?.[Math.min(p.wave.length-1,Math.floor(source/p.duration*p.wave.length))]||[0,0];return `<path d="M${i},${50+lo*48}V${50+hi*48}" stroke="currentColor"/>`;}).join('')}</svg>`;}if(p.kind==='notes')return `<svg viewBox="0 0 ${p.beats*4} 86" aria-hidden="true" preserveAspectRatio="none">${p.notes.map(n=>`<rect x="${n.start*4}" y="${108-n.pitch}" width="${n.length*4}" height="2" fill="currentColor"/>`).join('')}</svg>`;const steps=Array.from({length:p.steps},(_,i)=>p.matrix.reduce((n,r)=>n+!!r[i],0));return `<svg viewBox="0 0 ${p.steps*4} 20" aria-hidden="true" preserveAspectRatio="none">${steps.map((n,i)=>`<rect x="${i*4}" y="${20-n}" width="2" height="${n}" fill="currentColor"/>`).join('')}</svg>`;}
 function render(){if(gestures.size)return;const oldScroll=q('.pl-scroll')?.scrollLeft||0,active=root.contains(document.activeElement)?{id:document.activeElement.id,clip:document.activeElement.closest('[data-pl-clip]')?.dataset.plClip,data:Object.entries(document.activeElement.dataset||{})}:null;for(const [id,g]of gestures){try{g.element.releasePointerCapture(id)}catch{}}gestures.clear();const p=state(),patterns=getPatterns(),end=Math.max(32,playlistEnd(p),p.loopEnd),width=end*p.zoom,clip=selected()[0];if(!patterns.some(p=>p.id===source))source=currentId();selection=new Set([...selection].filter(id=>p.clips.some(c=>c.id===id)));
 root.innerHTML=`<div class="pl-intro"><h2>Playlist · build a song</h2><p>Place patterns on different tracks to play them together. Longer clips repeat their pattern. Tap a clip to edit; drag its body to move or its right handle to resize. Source edits update linked clips; Make unique protects other copies. 4 beats = 1 bar. Audio sources show actual decoded waveform peaks; source trim and independent speed/pitch are in Audio clips.</p></div><div class="pl-actions"><label>Pattern<select id="plPattern">${patterns.map(p=>`<option value="${esc(p.id)}" ${p.id===source?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button id="plAdd" class="btn primary">ADD TO PLAYLIST</button><button id="plNew" class="btn secondary">NEW PATTERN</button><button id="plSavePattern" class="btn secondary">SAVE PATTERN</button><button id="plEdit" class="btn secondary">EDIT SOURCE</button><button id="plTrack" class="btn secondary" ${p.tracks.length>=24?'disabled':''}>＋ TRACK</button></div><div class="pl-actions"><label>Snap<select id="plSnap">${[[4,'Bar'],[1,'Beat'],[.5,'Eighth'],[.25,'Sixteenth'],[.125,'32nd']].map(([n,s])=>`<option value="${n}" ${p.snap===n?'selected':''}>${s}</option>`).join('')}</select></label><label>Zoom<input id="plZoom" type="range" min="16" max="120" value="${p.zoom}"></label><label>Song position · beats<input id="plSeek" type="number" min="0" max="512" step="${p.snap}" value="${position.toFixed(2)}"></label><button id="plSeekGo" class="btn secondary">SEEK</button><label><input id="plLoop" type="checkbox" ${p.loop?'checked':''}> Loop region</label><label>Loop start · beats<input id="plLoopStart" type="number" min="0" max="511.875" step="${p.snap}" value="${p.loopStart}"></label><label>Loop end · beats<input id="plLoopEnd" type="number" min=".125" max="512" step="${p.snap}" value="${p.loopEnd}"></label><output id="plPosition" aria-live="off"></output><span>Time signature: 4/4</span><label>Sections · name:beat, comma separated<input id="plSections" maxlength="300" value="${esc((p.sections||[]).map(s=>s.name+':'+s.start).join(', '))}" placeholder="Intro:0, Verse:8, Chorus:32, Outro:56"></label></div><div class="pl-scroll" tabindex="0" role="region" aria-label="Song tracks and timeline"><div class="pl-board" style="width:${width+240}px;--beat:${p.zoom}px"><div class="pl-ruler"><span>TRACK / BAR</span><div>${Array.from({length:Math.ceil(end/4)},(_,i)=>`<button data-pl-seek="${i*4}" style="left:${i*4*p.zoom}px;width:${4*p.zoom}px" aria-label="Seek to bar ${i+1}">${i+1}</button>`).join('')}</div></div>${p.tracks.map(t=>`<div class="pl-row" data-pl-track="${esc(t.id)}"><div class="pl-track"><input data-pl-name="${esc(t.id)}" aria-label="Track name" maxlength="60" value="${esc(t.name)}"><input type="color" data-pl-color="${esc(t.id)}" aria-label="Track color" value="${t.color}"><label>Volume<input type="range" min="0" max="2" step=".01" data-pl-volume="${esc(t.id)}" value="${t.volume}"></label><label>Pan<input type="range" min="-1" max="1" step=".01" data-pl-pan="${esc(t.id)}" value="${t.pan}"></label><label><input type="checkbox" data-pl-mute="${esc(t.id)}" ${t.mute?'checked':''}>Mute</label><label><input type="checkbox" data-pl-solo="${esc(t.id)}" ${t.solo?'checked':''}>Solo</label><button data-pl-delete-track="${esc(t.id)}" ${p.tracks.length===1?'disabled':''} aria-label="Delete ${esc(t.name)} track">Remove track</button></div><div class="pl-lane" style="width:${width}px">${p.clips.filter(c=>c.trackId===t.id).map(c=>{const pattern=patterns.find(x=>x.id===c.patternId);return `<div role="group" tabindex="-1" data-pl-clip="${esc(c.id)}" aria-label="${esc(pattern.name)}, beat ${c.start}, ${c.length} beats" class="pl-clip ${selection.has(c.id)?'selected':''}" style="left:${c.start*p.zoom}px;width:${Math.max(28,c.length*p.zoom)}px;--clip:${t.color}"><button data-pl-select aria-pressed="${selection.has(c.id)}">${esc(pattern.name)}</button>${preview(pattern,c)}<button data-pl-resize="${esc(c.id)}" aria-label="Resize ${esc(pattern.name)}">↔</button></div>`;}).join('')}</div></div>`).join('')}<div class="pl-playhead" style="left:${240+position*p.zoom}px"></div></div></div><div class="pl-inspector"><label><input id="plMulti" type="checkbox" ${multi?'checked':''}> Select several clips (tap each)</label><span>${selection.size} selected</span><button id="plCopy">COPY</button><button id="plPaste" ${clipboard.length?'':'disabled'}>PASTE AT POSITION</button><button id="plDuplicate">DUPLICATE</button><button id="plSplit">SPLIT AT POSITION</button><button id="plUnique">MAKE UNIQUE</button><button id="plDelete">DELETE CLIPS</button><button id="plUndo" ${undo.length?'':'disabled'}>UNDO</button><button id="plRedo" ${redo.length?'':'disabled'}>REDO</button>${clip?`<label>Track<select id="plClipTrack">${p.tracks.map(t=>`<option value="${esc(t.id)}" ${t.id===clip.trackId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Clip start · beats<input id="plClipStart" type="number" min="0" max="512" step="${p.snap}" value="${clip.start}"></label><label>Length / repeat · beats<input id="plClipLength" type="number" min=".125" max="512" step="${p.snap}" value="${clip.length}"></label><label>Source trim · beats<input id="plClipOffset" type="number" min="0" max="512" step="${p.snap}" value="${clip.offset}"></label>`:''}</div><div class="pl-actions"><button id="plWAV" class="btn primary">EXPORT PLAYLIST WAV</button><button id="plMP3" class="btn secondary">EXPORT PLAYLIST MP3</button><p>Save the whole project with the familiar Save button. Up to ${PLAYLIST_LIMITS.tracks} tracks / 512 clips / 128 bars. Export: five minutes. Pattern previews show drum hits, instrument notes or decoded audio waveforms.</p></div>`;
 q('.pl-scroll').scrollLeft=oldScroll;q('#plMulti').onchange=e=>multi=e.target.checked;q('#plPattern').onchange=e=>source=e.target.value;q('#plAdd').onclick=()=>act(()=>place(source,clip?.trackId||p.tracks[0].id,snap(position)));q('#plNew').onclick=()=>{addPattern();source=currentId();render()};q('#plSavePattern').onclick=()=>{savePattern(source);render()};q('#plEdit').onclick=()=>editPattern(source);
 q('#plTrack').onclick=()=>act(()=>p.tracks.push({id:uid(),name:'Track '+(p.tracks.length+1),color:'#859fd1',volume:1,pan:0,mute:false,solo:false}));
 for(const [suffix,field]of [['name','name'],['color','color'],['volume','volume'],['pan','pan'],['mute','mute'],['solo','solo']])all(`[data-pl-${suffix}]`).forEach(el=>el.onchange=()=>act(()=>{p.tracks.find(t=>t.id===el.dataset['pl'+suffix[0].toUpperCase()+suffix.slice(1)])[field]=['mute','solo'].includes(field)?el.checked:['volume','pan'].includes(field)?+el.value:el.value;}));
 all('[data-pl-delete-track]').forEach(el=>el.onclick=()=>act(()=>{p.tracks=p.tracks.filter(t=>t.id!==el.dataset.plDeleteTrack);p.clips=p.clips.filter(c=>c.trackId!==el.dataset.plDeleteTrack)}));
 q('#plSnap').onchange=e=>act(()=>p.snap=+e.target.value);q('#plZoom').onchange=e=>act(()=>p.zoom=+e.target.value);
 q('#plSeekGo').onclick=()=>{position=Math.max(0,Math.min(512,+q('#plSeek').value||0));seek(position);render()};all('[data-pl-seek]').forEach(el=>el.onclick=()=>{position=+el.dataset.plSeek;seek(position);render()});
 for(const [id,key]of [['plLoop','loop'],['plLoopStart','loopStart'],['plLoopEnd','loopEnd']])q('#'+id).onchange=e=>act(()=>{p[key]=key==='loop'?e.target.checked:+e.target.value;if(p.loopEnd<=p.loopStart||p.loopStart<0||p.loopEnd>512)throw Error('Choose an end after the loop start, within 128 bars.');});
 q('#plSections').onchange=e=>act(()=>{p.sections=e.target.value.trim()?e.target.value.split(',').map(row=>{const parts=row.trim().split(':');if(parts.length!==2||!parts[0]||parts[0].length>40||!Number.isFinite(+parts[1])||+parts[1]<0||+parts[1]>512)throw Error('Use section name:beat, within 0–512.');return{name:parts[0],start:+parts[1]};}):[];if(p.sections.length>16)throw Error('Use up to 16 section markers.');});q('#plCopy').onclick=()=>{clipboard=structuredClone(selected());render()};q('#plPaste').onclick=()=>act(()=>{if(p.clips.length+clipboard.length>512)throw Error('Clip limit reached.');const first=Math.min(...clipboard.map(c=>c.start)),copy=clipboard.map(c=>({...c,id:uid(),trackId:p.tracks.some(t=>t.id===c.trackId)?c.trackId:p.tracks[0].id,start:c.start-first+snap(position)}));if(copy.some(c=>c.start+c.length>512))throw Error('Paste within 128 bars.');p.clips.push(...copy);selection=new Set(copy.map(c=>c.id));});
 q('#plDuplicate').onclick=()=>act(()=>{const rows=selected(),end=Math.max(...rows.map(c=>c.start+c.length)),start=Math.min(...rows.map(c=>c.start));if(!rows.length)return;if(p.clips.length+rows.length>512||rows.some(c=>c.start+end-start+c.length>512))throw Error('Duplicate within the song limits.');const copies=rows.map(c=>({...c,id:uid(),start:c.start+end-start}));p.clips.push(...copies);selection=new Set(copies.map(c=>c.id));});
 q('#plSplit').onclick=()=>act(()=>{for(const c of selected()){const at=snap(position);if(at<=c.start||at>=c.start+c.length)continue;if(p.clips.length>=512)throw Error('Clip limit reached.');p.clips.push({...c,id:uid(),start:at,length:c.length-(at-c.start),offset:(c.offset+at-c.start)%duration(patterns.find(p=>p.id===c.patternId))});c.length=at-c.start;}});
 q('#plUnique').onclick=()=>act(()=>{for(const c of selected()){const copy=structuredClone(patterns.find(x=>x.id===c.patternId));copy.id=uid();copy.name+=' unique';patterns.push(copy);c.patternId=copy.id;source=copy.id;}});
 q('#plDelete').onclick=()=>act(()=>{p.clips=p.clips.filter(c=>!selection.has(c.id));selection.clear()});
 for(const [id,from,to]of [['plUndo',undo,redo],['plRedo',redo,undo]])q('#'+id).onclick=()=>{if(!from.length)return;changing();to.push(snapshot());restore(from.pop());selection.clear();changed();render()};
 if(clip)for(const [id,key]of [['plClipTrack','trackId'],['plClipStart','start'],['plClipLength','length'],['plClipOffset','offset']])q('#'+id).onchange=e=>act(()=>{clip[key]=key==='trackId'?e.target.value:+e.target.value;if(!Number.isFinite(clip.start+clip.length+clip.offset)||clip.start<0||clip.length<.125||clip.offset<0||clip.offset>512||clip.start+clip.length>512)throw Error('Keep the clip within the song limits.');});
 q('#plWAV').onclick=()=>exportSong('wav');q('#plMP3').onclick=()=>exportSong('mp3');
 all('[data-pl-clip]').forEach(el=>{const choose=()=>{source=p.clips.find(c=>c.id===el.dataset.plClip).patternId;const multi=q('#plMulti').checked;if(!multi)selection.clear();selection.has(el.dataset.plClip)?selection.delete(el.dataset.plClip):selection.add(el.dataset.plClip);render()};el.querySelector('[data-pl-select]').onclick=e=>{if(e.detail===0)choose()};el.querySelector('[data-pl-resize]').onclick=e=>{if(e.detail===0)choose()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}};el.onpointerdown=e=>{if(e.button>0)return;e.preventDefault();const id=el.dataset.plClip,c=p.clips.find(c=>c.id===id),resize=!!e.target.closest('[data-pl-resize]');if([...gestures.values()].some(g=>g.ids.includes(id)))return;el.setPointerCapture(e.pointerId);gestures.set(e.pointerId,{element:el,id,ids:[id],x:e.clientX,y:e.clientY,resize,clip:{...c},dx:0,dy:0});};el.onpointermove=e=>{const g=gestures.get(e.pointerId);if(!g)return;g.dx=e.clientX-g.x;g.dy=e.clientY-g.y;if(g.resize)el.style.width=Math.max(28,(g.clip.length+snap(g.dx/p.zoom))*p.zoom)+'px';else el.style.transform=`translate(${snap(g.dx/p.zoom)*p.zoom}px,${g.dy}px)`;};const release=(e,cancel)=>{const g=gestures.get(e.pointerId);if(!g)return;gestures.delete(e.pointerId);try{el.releasePointerCapture(e.pointerId)}catch{}if(cancel){el.style.transform='';el.style.width=Math.max(28,g.clip.length*p.zoom)+'px';render();return;}if(Math.hypot(g.dx,g.dy)<5&&!g.resize){choose();return;}act(()=>{const c=p.clips.find(c=>c.id===g.id);if(g.resize)c.length=Math.max(.125,Math.min(512-c.start,g.clip.length+snap(g.dx/p.zoom)));else{c.start=Math.max(0,Math.min(512-c.length,g.clip.start+snap(g.dx/p.zoom)));const rows=[...all('[data-pl-track]')],index=rows.findIndex(r=>r.dataset.plTrack===g.clip.trackId),height=rows[index].getBoundingClientRect().height;c.trackId=p.tracks[Math.max(0,Math.min(p.tracks.length-1,index+Math.round(g.dy/height)))].id;}selection=new Set([c.id]);});};el.onpointerup=e=>release(e,false);el.onpointercancel=e=>release(e,true);});
 update(position);if(active){const target=active.id?q('#'+active.id):[...all('button,input,select')].find(el=>(!active.clip||el.closest('[data-pl-clip]')?.dataset.plClip===active.clip)&&active.data.length&&active.data.every(([k,v])=>el.dataset[k]===v));target?.focus({preventScroll:true});}
 }
 function update(beat){position=beat;const head=q('.pl-playhead');if(head)head.style.left=240+beat*state().zoom+'px';const text=q('#plPosition');if(text)text.textContent=`Bar ${Math.floor(beat/4)+1} · beat ${(beat%4+1).toFixed(1)} · ${playlistEnd(state())/4} bars · ${(playlistEnd(state())*60/getBpm()).toFixed(1)} s`;}
 return{render,update,addCurrent(id=currentId()){source=id;act(()=>place(source,state().tracks[0].id,snap(position)));},cancel(){const had=gestures.size;for(const [id,g]of gestures){try{g.element.releasePointerCapture(id)}catch{}g.element.style.transform='';g.element.style.width=Math.max(28,g.clip.length*state().zoom)+'px';}gestures.clear();if(had&&!root.hidden)render();},dispose(){this.cancel();root.replaceChildren();}};
}
